const CACHE='curiosity-lab-v1-6-video-20261125',ROOT=new URL('./',self.location).href;
const FILES=['./','./index.html','./style.css?v=20261125video','./app.js?v=20261125video','./rooms.js','./lab.css?v=20261125video','./lab-catalog.js?v=20261125video','./labs.js?v=20261125video','./channels.js?v=20261125video','./channels.json','./content.json','./update-status.json','./manifest.webmanifest','./assets/icon-192.png','./assets/icon-512.png','./assets/space.jpg','./assets/jelly.jpg','./assets/forest.jpg','./assets/moon.jpg','./assets/ocean.jpg','./assets/city.jpg','./assets/history.jpg','./assets/laundry.jpg','./assets/kitchen.jpg','./assets/tools.jpg','./assets/writing.jpg'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES.map(f=>new URL(f,ROOT).href))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('curiosity-lab-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request,{cache:'no-cache'}).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(async()=>{const cached=await caches.match(e.request);if(cached){const headers=new Headers(cached.headers);headers.set('X-Curiosity-Offline','1');return new Response(cached.body,{status:cached.status,statusText:cached.statusText,headers})}if(e.request.mode==='navigate')return caches.match(new URL('./index.html',ROOT).href);return new Response('Offline',{status:503})}))});
